(function(){"use strict";app.factory("etiquetaService",function(n){let i="Inventario/Etiqueta/",t={};return t.getAll=function(t){return n.getData("get",i+"Get/"+t).then(n=>{if(n.code==="0")throw n;if(n.code==="1"){let t=JSON.parse(n.payload);return t.map(n=>({idEtiqueta:n.idEtiqueta,descripcion:n.descripcion,etiquetas:n.etiquetas,estado:n.estado}))}})},t.create=function(t){return n.getData("post",i+"Insert?json="+JSON.stringify(t)).then(n=>n.code==="0"?n:n.code==="1"?n:void 0)},t.update=function(t,r){return n.getData("put",i+"Update/"+t+"/?json="+JSON.stringify(r)).then(n=>n.code==="0"?n:n.code==="1"?n:void 0)},t.delete=function(t){return n.getData("delete",i+"Delete/"+t).then(n=>n.code==="0"?n:n.code==="1"?n:void 0)},t})})(window.angular);